# Maya-scene -> USD conversion script (Maya -> Blender pull). Generated by MayaSceneImport -- do not edit by hand.

"""Open a Maya scene headlessly (mayapy) and export it as USD for a Blender import.

The USD sibling of ``templates/_import_scene.py`` (the FBX route), selected via
``import_scene(via="usd")``. Runs under ``mayapy`` via
``pythontk.run_script_to_artifact``, which judges success by the exported USD's
existence -- NOT the exit code (standalone teardown is a known crasher, hence the
``os._exit`` below).

Where the FBX route must downgrade every modern shader to phong and sidecar the
PBR textures in a ``.manifest.json``, USD needs neither: ``mayaUSDExport``'s
registry shading converts the standardSurface family to ``UsdPreviewSurface``
natively (metallic / roughness / normal / emissive textures included), which
Blender's importer wires straight into a Principled BSDF. The one translation
still needed is the ShaderFX game-shader family (StingrayPBS) -- the registry
has no exporter for it -- which is swapped for an equivalent ``standardSurface``
so even its packed metallic map gets a real USD slot (the FBX route can only
carry that via the manifest rebuild).

Underscore-prefixed: hidden from the bridge panel's template list (this is not a
user-pickable send recipe; it belongs to the pull engine).
"""

# Dependency-free Maya Python: no mayatk/blendertk imports (the target machine's
# mayapy only has Maya's own modules).
import math
import os
import re
import sys
import traceback

SRC_PATH = r"__SRC_PATH__"
OUT_USD = r"__OUT_USD__"
INCLUDE_ANIMATION = __INCLUDE_ANIMATION__

# ShaderFX game shaders: the mayaUsd registry has no exporter for them (they
# would arrive as displayColor-only). Translated to standardSurface below.
STINGRAY_SHADER_TYPES = ("StingrayPBS", "ShaderfxShader")


def _ns_safe(name):
    """*name* with namespace colons flattened (``ns:mat`` -> ``ns_mat``) -- nodes
    we CREATE live at the root namespace under a colon-free name (the FBX
    template's rule; referenced scenes arrive namespaced)."""
    return name.replace(":", "_")


def _plug_source(cmds, attr):
    """Return the source plug connected into *attr*, or None."""
    try:
        cons = cmds.listConnections(attr, source=True, destination=False, plugs=True)
        return cons[0] if cons else None
    except Exception:
        return None


def _get_first(cmds, node, names, default):
    """First readable attribute value among *names*, else *default*."""
    for name in names:
        try:
            value = cmds.getAttr(f"{node}.{name}")
            return value[0] if isinstance(value, list) else value
        except Exception:
            continue
    return default


def _resolve_workspace(cmds, scene_path):
    """Open the Maya project owning *scene_path* (nearest workspace.mel above it).

    Without it, headless Maya cannot resolve project-relative texture paths
    (``sourceimages/...``) and the USD would carry unresolvable asset refs --
    the same pink-materials failure the FBX route fixed this way.
    """
    directory = os.path.dirname(os.path.abspath(scene_path))
    while True:
        if os.path.isfile(os.path.join(directory, "workspace.mel")):
            try:
                cmds.workspace(directory, openWorkspace=True)
                return directory
            except Exception:
                return None
        parent = os.path.dirname(directory)
        if parent == directory:
            return None
        directory = parent


def _open_scene(cmds, path):
    """Open *path*, tolerating the RuntimeError noise of a scene that LOADED but
    reported errors -- missing renderer plugins, unknown nodes (routine for
    production scenes on a vanilla mayapy; the FBX template's rule). A failed
    open -- nothing loaded -- still raises."""
    try:
        cmds.file(path, open=True, force=True, ignoreVersion=True,
                  loadReferenceDepth="all")
    except RuntimeError as error:
        opened = cmds.file(query=True, sceneName=True) or ""
        if os.path.normcase(os.path.abspath(opened)) != os.path.normcase(
                os.path.abspath(path)):
            raise
        print("scene opened with load errors (tolerated): {}".format(error))


def _translate_stingray_to_ss(cmds, mat, ss):
    """StingrayPBS -> standardSurface: every PBR slot gets a NATIVE USD home.

    Unlike the FBX route's phong downgrade, metallic and roughness maps ride
    as real UsdPreviewSurface inputs (single-channel reads via ``outColorR``
    / ``outAlpha``). ``use_*_map`` toggles are honored. AO has no
    standardSurface slot and is dropped with a note.
    """
    def use(flag):
        return bool(_get_first(cmds, mat, (flag,), 0))

    color_src = _plug_source(cmds, f"{mat}.TEX_color_map")
    if color_src and use("use_color_map"):
        cmds.connectAttr(color_src, f"{ss}.baseColor", force=True)
    else:
        c = _get_first(cmds, mat, ("base_color",), (0.5, 0.5, 0.5))
        cmds.setAttr(f"{ss}.baseColor", c[0], c[1], c[2], type="double3")

    normal_src = _plug_source(cmds, f"{mat}.TEX_normal_map")
    if normal_src and use("use_normal_map"):
        # Tangent-space bump2d chain -- the pattern the registry exporter
        # recognizes and writes as a UsdUVTexture normal input.
        file_node = normal_src.split(".")[0]
        bump = cmds.shadingNode(
            "bump2d", asUtility=True, name=f"{_ns_safe(mat)}_usdsafe_bump"
        )
        cmds.setAttr(f"{bump}.bumpInterp", 1)  # tangent-space normals
        try:
            cmds.connectAttr(f"{file_node}.outAlpha", f"{bump}.bumpValue", force=True)
        except Exception:
            pass
        cmds.connectAttr(f"{bump}.outNormal", f"{ss}.normalCamera", force=True)

    metal_src = _plug_source(cmds, f"{mat}.TEX_metallic_map")
    if metal_src and use("use_metallic_map"):
        file_node = metal_src.split(".")[0]
        cmds.connectAttr(f"{file_node}.outColorR", f"{ss}.metalness", force=True)
    else:
        cmds.setAttr(f"{ss}.metalness", _get_first(cmds, mat, ("metallic",), 0.0))

    rough_src = _plug_source(cmds, f"{mat}.TEX_roughness_map")
    if rough_src and use("use_roughness_map"):
        file_node = rough_src.split(".")[0]
        cmds.connectAttr(
            f"{file_node}.outColorR", f"{ss}.specularRoughness", force=True
        )
    else:
        cmds.setAttr(
            f"{ss}.specularRoughness", _get_first(cmds, mat, ("roughness",), 0.4)
        )

    # Gated on intensity like the FBX route: a wired map with intensity 0
    # emits nothing in Maya and must not glow in Blender.
    emis_src = _plug_source(cmds, f"{mat}.TEX_emissive_map")
    if (emis_src and use("use_emissive_map")
            and _get_first(cmds, mat, ("emissive_intensity",), 1.0) > 0.0):
        cmds.connectAttr(emis_src, f"{ss}.emissionColor", force=True)
        cmds.setAttr(f"{ss}.emission", 1.0)

    if _plug_source(cmds, f"{mat}.TEX_ao_map"):
        print(f"{mat}: standardSurface has no AO slot -- ao map not carried")


def usd_safe_materials(cmds):
    """Swap ShaderFX game shaders for standardSurface on their shading groups.

    ONE standardSurface per source material (the FBX route's memoization rule:
    per-SG translation explodes into duplicates on production scenes). The
    scene is throwaway -- nothing is restored. The standardSurface family
    itself passes through untouched (the registry exports it natively).
    """
    translated = {}
    for sg in cmds.ls(type="shadingEngine") or []:
        try:
            src = _plug_source(cmds, f"{sg}.surfaceShader")
            if not src:
                continue
            mat = src.split(".")[0]
            if mat in translated:
                cmds.connectAttr(
                    f"{translated[mat]}.outColor", f"{sg}.surfaceShader", force=True
                )
                continue
            if cmds.nodeType(mat) not in STINGRAY_SHADER_TYPES:
                continue
            ss = cmds.shadingNode(
                "standardSurface", asShader=True, name=f"{_ns_safe(mat)}_usdsafe"
            )
            _translate_stingray_to_ss(cmds, mat, ss)
            cmds.connectAttr(f"{ss}.outColor", f"{sg}.surfaceShader", force=True)
            translated[mat] = ss
            print(f"usd-safe: {mat} -> {ss}")
        except Exception:
            print(f"usd-safe translation skipped for {sg}:")
            traceback.print_exc()


# Drivers that move things WITHOUT keys of their own: their motion cannot be
# inferred from key times, so they force the full playback range.
_UNKEYED_DRIVERS = (
    "parentConstraint", "pointConstraint", "orientConstraint", "scaleConstraint",
    "aimConstraint", "poleVectorConstraint", "geometryConstraint",
    "normalConstraint", "tangentConstraint", "expression", "ikHandle",
    "motionPath",
)


def _animation_frame_range(cmds):
    """The frames actually worth sampling, or ``None`` for a static export.

    USD has no animation *curves* -- ``frameRange`` makes mayaUSDExport write a
    time sample per frame for EVERY prim, so the range is a direct multiplier on
    export cost (measured on a 755-mesh production module with a 1-200 playback
    range: 234s with the full range vs 1.8s static, byte-identical result).

    So sample only what moves:
      * nothing animated                -> ``None``  (static export)
      * unkeyed drivers present         -> the full playback range (their motion
                                           can't be derived from key times)
      * plain keyframes only            -> the keys' own span, clamped to the
                                           playback range (a stray far-out key
                                           must not multiply the sample count,
                                           and frames outside the scene's own
                                           time are not what the user sees)

    Only TIME-based curves (``animCurveT*``) count: ``animCurveU*`` are
    set-driven keys whose "times" are driver *values*, not frames -- their
    motion over time comes from whatever animates the driver, which is itself a
    time curve.
    """
    playback = (
        cmds.playbackOptions(query=True, animationStartTime=True),
        cmds.playbackOptions(query=True, animationEndTime=True),
    )
    if cmds.ls(type=_UNKEYED_DRIVERS):
        return playback

    curves = cmds.ls(
        type=("animCurveTA", "animCurveTL", "animCurveTU", "animCurveTT")
    ) or []
    if not curves:
        return None
    # ONE query for every curve -- per-curve calls cost a round trip each, and a
    # rigged scene carries thousands.
    times = cmds.keyframe(curves, query=True, timeChange=True) or []
    if not times:
        return None

    # floor/ceil, not int(): int() truncates toward zero, which would clip a key
    # at 20.5 down to 20 (losing motion) and mis-round negative frames.
    start = max(playback[0], math.floor(min(times)))
    end = min(playback[1], math.ceil(max(times)))
    if end < start:  # keys live entirely outside the scene's own time
        return None
    return (start, end)


def export_usd(cmds):
    """Whole-scene ``mayaUSDExport`` with per-flag tolerance across mayaUsd versions.

    ``cmds`` rejects the whole call on one unknown flag (TypeError), so a flag
    this mayaUsd doesn't know is dropped and the call retried -- the mirror of
    the FBX template's per-flag MEL tolerance. ``defaultMeshScheme='none'`` is
    load-bearing: the exporter defaults to catmullClark, which Blender would
    then subdivide-smooth meshes Maya displayed as plain polys.
    """
    kwargs = {
        "file": OUT_USD,
        "shadingMode": "useRegistry",
        "convertMaterialsTo": ["UsdPreviewSurface"],
        # exportInstances is DELIBERATELY off (measured on Maya 2025 / mayaUsd).
        # When the scene holds instanced shapes, material export degrades badly
        # and can collapse outright: on a probe scene whose only instances were
        # two cubes, `def Material` went 3 -> 0 and `material:binding` 4 -> 0
        # with the flag on -- taking `mat_solo`, bound ONLY to a non-instanced
        # mesh, with it. (On other scenes only the instanced prims lose their
        # binding; either way objects arrive unshaded.) It also lands geometry
        # in a `prototypes` collection of collection-instance Empties, which a
        # pull-for-editing user cannot edit per-object, and drops per-instance
        # material assignments, since all instances share one prototype.
        # Flattening does NOT mean losing instances. USD's own instancing model
        # cannot give Blender what production needs -- measured both ways: the
        # importer turns instanceable prims into collection-instance Empties
        # under a `prototypes` collection (uneditable), and disabling that
        # (`support_scene_instancing=False`) yields real objects with ZERO data
        # sharing. Neither is Blender's linked-duplicate model. So the export
        # flattens (materials + clean structure), `collect_instance_groups`
        # records the relationship in the sidecar, and the Blender side rebuilds
        # native shared mesh datablocks from it -- VDATS_RF lands at 628
        # datablocks for 755 objects, matching the FBX route's 627.
        # Pinned by the e2e's e2e_inst_* trap.
        "exportInstances": False,
        "mergeTransformAndShape": True,
        "exportUVs": True,
        "exportVisibility": True,
        "exportBlendShapes": True,
        "exportSkels": "auto",
        "exportSkin": "auto",
        "defaultMeshScheme": "none",
        # The USD lives in the temp dir; relative asset refs would be
        # unresolvable in Blender (the FBX route's path_mode=ABSOLUTE mirror).
        "exportRelativeTextures": "absolute",
    }
    # Sample only the frames that carry motion -- see _animation_frame_range for
    # the measured cost of getting this wrong.
    frame_range = _animation_frame_range(cmds) if INCLUDE_ANIMATION else None
    if frame_range:
        kwargs["frameRange"] = frame_range
        print("USD export: sampling frames {}-{}".format(*frame_range))
    else:
        print("USD export: no animation to sample -- static export (no frameRange)")
    while True:
        try:
            cmds.mayaUSDExport(**kwargs)
            return
        except TypeError as e:
            match = re.search(r"'(\w+)'", str(e))
            key = match.group(1) if match else None
            if key and key in kwargs and key != "file":
                print("USD flag skipped (unsupported by this mayaUsd): " + key)
                del kwargs[key]
                continue
            raise


def _sanitize_prim_name(name):
    """Mirror of the USD prim-name rewrite (probe-verified: mayaUSDExport turns
    ``ref:nsCube`` into ``ref_nsCube``): every char outside ``[A-Za-z0-9_]``
    becomes ``_``, and a leading digit is PREFIXED with ``_``. The sidecar must
    record what the exporter actually writes. Keep identical to the mayatk twin.
    """
    if not name:
        return "_"
    name = re.sub(r"[^A-Za-z0-9_]", "_", name)
    if name[0].isdigit():
        name = "_" + name
    return name


def collect_instance_groups(cmds):
    """Maya instance sets -> ``[[sanitized prim paths sharing one shape], ...]``.

    The export FLATTENS instances (see ``exportInstances`` above), which is what
    keeps materials intact -- but flattening alone would hand Blender N
    independent meshes and break the scene's memory profile. USD cannot carry
    the relationship for us: its instancing model produces read-only prototypes
    that Blender materializes as collection-instance Empties, not the linked
    duplicates a Blender artist edits (measured: both import modes fail, one
    with `prototypes` clutter, the other with zero data sharing).

    So the RELATIONSHIP travels as data, in the same sidecar the FBX route
    already uses, and ``_apply_instance_manifest`` rebuilds Blender-native
    shared mesh datablocks from it. Recorded, never inferred: hashing geometry
    would also fuse coincidentally-identical meshes, so editing one would
    silently change another.

    Recorded as FULL PRIM PATHS with every segment sanitized -- what
    ``mergeTransformAndShape=True`` writes (probe-verified: ``|g1|wheel`` ->
    ``/g1/wheel``, namespaced ``ref:nsCube`` -> ``/ref_nsCube``). Paths, not
    leaf names: prim paths are unique, so duplicate leaves stay matchable
    through Blender's ``.001`` collision renames. Two transforms whose paths
    sanitize identically (``ns:cube`` beside ``ns_cube``) are renamed apart
    unpredictably by the exporter, so a collision touching a recorded member
    fails the export loudly rather than shipping a sidecar that cannot match.
    """
    def prim_path(dag_path):
        return "/" + "/".join(
            _sanitize_prim_name(seg) for seg in dag_path.split("|") if seg
        )

    all_paths = {}
    for transform in cmds.ls(type="transform", long=True) or []:
        all_paths.setdefault(prim_path(transform), []).append(transform)

    groups = []
    for shape in cmds.ls(type="mesh", noIntermediate=True) or []:
        try:
            parents = cmds.listRelatives(shape, allParents=True, fullPath=True) or []
        except Exception:
            continue
        if len(parents) > 1:  # >1 parent transform == a Maya instance set
            groups.append([prim_path(p) for p in parents])

    colliding = {}
    for group in groups:
        for path in group:
            if len(all_paths.get(path, [])) > 1:
                colliding[path] = all_paths[path]
    if colliding:
        raise RuntimeError(
            "Transform paths collide after USD prim sanitization -- the "
            "exporter renames them apart unpredictably, so the instance sets "
            "could not be matched on the Blender side. Rename to distinct "
            "prim-safe names or pull via FBX: "
            + "; ".join(
                "{} <- {}".format(k, v) for k, v in sorted(colliding.items())
            )
        )
    return groups


def write_manifest(cmds):
    """Sidecar beside the USD carrying what USD itself cannot: instance groups.

    ALWAYS written for the USD route (empty groups included), so the Blender
    side can tell "no instances" from "sidecar lost" -- it REQUIRES the file.
    Raises on failure; main() then withholds the USD artifact, so the parent's
    judged-by-artifact contract reports a failed conversion instead of shipping
    a payload that would import silently flattened.
    """
    import json

    groups = collect_instance_groups(cmds)
    with open(OUT_USD + ".manifest.json", "w", encoding="utf-8") as fh:
        json.dump({"version": 2, "format": "paths", "instances": groups}, fh)
    print(
        "instance manifest: {} group(s) covering {} transforms".format(
            len(groups), sum(len(g) for g in groups)
        )
    )


def main():
    import maya.standalone

    maya.standalone.initialize(name="python")
    import maya.cmds as cmds

    workspace = _resolve_workspace(cmds, SRC_PATH)
    print("workspace: " + (workspace or "none found (Maya fallback resolution only)"))
    _open_scene(cmds, SRC_PATH)
    usd_safe_materials(cmds)
    if not cmds.pluginInfo("mayaUsdPlugin", query=True, loaded=True):
        cmds.loadPlugin("mayaUsdPlugin")
    export_usd(cmds)
    # AFTER the export: the sidecar describes the scene the USD was written
    # from, and a failed export must not leave a stale manifest behind. A
    # failed MANIFEST must not leave the USD behind either -- success is
    # judged by the artifact, and a USD without its sidecar would import
    # silently flattened.
    try:
        write_manifest(cmds)
    except Exception:
        try:
            os.remove(OUT_USD)
        except OSError:
            pass
        raise


try:
    main()
except Exception:
    traceback.print_exc()
    sys.stdout.flush()
    sys.stderr.flush()
    os._exit(1)
# Success is judged by the artifact; skip standalone teardown (known access violations).
sys.stdout.flush()
os._exit(0)
